function fallbackSave(blob,fn){try{var u=URL.createObjectURL(blob),a=document.createElement("a");a.href=u;a.download=fn;document.body.appendChild(a);a.click();setTimeout(function(){URL.revokeObjectURL(u);a.remove();},1500);toast("Downloading company profile\u2026");}catch(e){toast("Download unavailable.");}}
function downloadProfile(){var blob=buildPDF();if(!blob)return;var fn="YEC-Management-Company-Profile.pdf";if(window.claude&&window.claude.use){claude.use("downloads").then(function(dl){if(!dl){fallbackSave(blob,fn);return;}dl.save({filename:fn,data:blob}).then(function(){toast("Company profile ready.");}).catch(function(err){if(err&&err.code==="declined")return;fallbackSave(blob,fn);});}).catch(function(){fallbackSave(blob,fn);});}else fallbackSave(blob,fn);}
function wireDownloads(){["dl-svc","dl-contact","dl-home","dl-nav"].forEach(function(id){var b=document.getElementById(id);if(b)b.addEventListener("click",downloadProfile);});}
function commonInit(){applyImages();buildServices();buildClients();buildCreds();navBits();enquiry();wireDownloads();}

(function(){
  var file=(location.pathname.split("/").pop()||"index.html")||"index.html";if(file==="")file="index.html";
  document.querySelectorAll("[data-page]").forEach(function(el){if(el.getAttribute("data-page")===file){var ni=el.closest(".navitem");if(ni)ni.classList.add("active");}});
  commonInit();revealBits(document);
  if(document.getElementById("svc-grid")&&/^#s-\d+$/.test(location.hash)){var box=document.querySelector(location.hash);if(box&&window.openSvc){openSvc(box,true);setTimeout(function(){box.scrollIntoView({behavior:reduce?"auto":"smooth",block:"center"});},140);}}
})();
